INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nora & Magic That Does Not Turn Back Time', '“Don’t use formal speech. Please.” That was the first thing she asked of me when I woke up. I couldn’t remember anything—not who she was, with her amber eyes, nor how I ended up here. Nothing. And yet, she told me to call her Nora.' FROM games WHERE igdb_id = 348882 ON CONFLICT (game_id, language_code) DO NOTHING;
