INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mononoke Chigiri', 'After one thousand years, the great yokai “Bake neko,” who was sealed away by the protagonist’s ancestor Abe no Seimei, begins the process of resurfacing in the world once again. The protagonist, an onmyoji, confronts the Great Yokai alongside the yokai that appear before her…' FROM games WHERE igdb_id = 343948 ON CONFLICT (game_id, language_code) DO NOTHING;
