INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pal-Mon', 'A thought-provoking indie game developed in Godot that uses casual mechanics to spark a conversation about creativity and fairness in gaming. You perform pointless tasks while The Developer talks at you. Satirical humor, goofy artwork, and an unsurprising end make this game worth playing--maybe.' FROM games WHERE igdb_id = 393801 ON CONFLICT (game_id, language_code) DO NOTHING;
