INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Anomalies', 'A slow-burning psychological horror where the fear comes not from monsters, but from the unknown. Each step leads you back to the same room—familiar, yet subtly wrong. The silence weighs heavy, the air feels off, and the deeper you stare, the stronger the sense that something is staring back.' FROM games WHERE igdb_id = 337582 ON CONFLICT (game_id, language_code) DO NOTHING;
