INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Labubu Battle Royale', 'Labubu Battle Royale plunges you into a vivid, living forest where every corner hides danger and excitement! Feel the adrenaline as you soar above the treetops, the wind rushing past, and prepare to land in a world where only the sharpest and quickest survive. The forest is alive with movement and sounds—rustling leaves, distant shouts, and the echo of distant gunfire. Every step could lead to glory or disaster, and every choice matters in your quest to become the ultimate survivor.' FROM games WHERE igdb_id = 380507 ON CONFLICT (game_id, language_code) DO NOTHING;
