INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anomalous Coffee Machine 2', 'In this game, meet a mysterious girl who demands you use an "Anomalous Coffee Machine". Type any word to create a drink, then choose who drinks: her or you. Some cups whisper, some scream, some change what you are. She watches quietly, like she already knows what you’ll choose. Now it''s your turn!' FROM games WHERE igdb_id = 359627 ON CONFLICT (game_id, language_code) DO NOTHING;
