INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chess Force', 'Chess Force! The wicked MAGNUS and his evil minions have taken taken over the moon with their dark chess powers. You, the KING, will earn PAWNS from each boss battle. Spend your hard-earned ELO to PROMOTE your pawns and add to your firepower. Can you become a GRANDMASTER and save the moon?' FROM games WHERE igdb_id = 338917 ON CONFLICT (game_id, language_code) DO NOTHING;
