INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Master Detective', 'Master Detective is a lighthearted spot-the-difference game where you explore five charming cartoon locations such as a hospital, bank, and detective office, each hiding three subtle differences for you to uncover; with no timers, hints, or limits on attempts, the experience is simple, relaxed, and focused entirely on testing your observation skills as you work through every scene to prove you’ve got what it takes to become the Master Detective.' FROM games WHERE igdb_id = 380651 ON CONFLICT (game_id, language_code) DO NOTHING;
