INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cazzarion: Raccoon Valley', '"Cazzarion: Raccoon Valley" is a relaxing nature adventure where you play as a curious raccoon exploring a lush valley filled with rivers, a serene lake, dense trees, and open meadows. Roam freely through the landscape in search of tasty critters like snails, worms, frogs, and more. With no enemies, it''s all about foraging, exploring, and enjoying the peaceful rhythm of the wild.' FROM games WHERE igdb_id = 361348 ON CONFLICT (game_id, language_code) DO NOTHING;
