INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eldritch Bulwark', 'An explosive tower defense experience like no other. Protect a crab colony from waves of invaders. In Eldritch Bulwark, you''ll place barricades, deploy specialized units, and use traps on various levels. You''ll encounter diverse enemies, including armored brutes, ranged bone-throwers, and ducks that multiply when defeated, requiring you to adapt your strategy. Your available defenses range from melee units to explosive traps.' FROM games WHERE igdb_id = 351180 ON CONFLICT (game_id, language_code) DO NOTHING;
