INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alentejo: The Tinto & The Ugly', 'Welcome back to the nostalgic Old Alentejo. In this historical 19th-century European western, help Gildo, Dolores, and Pepe in their quest to fight Baron Tinto and his oppressive laws. To do so, you’ll need to cross the historic border, explore new locations, discover more items, allies, and… new enemies! The Tinto has never meant so much to so many people in so many ways!' FROM games WHERE igdb_id = 374551 ON CONFLICT (game_id, language_code) DO NOTHING;
