INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Space Between', 'A 2D, open-world indie combat RPG set in an unstable world parallel to ours. Fight chaotic entities and bosses, explore broken worlds, and collect unique items to customize your loadout. Warp the fabric of time and space, and discover new unstable elements to grow your power and reach victory.' FROM games WHERE igdb_id = 378418 ON CONFLICT (game_id, language_code) DO NOTHING;
