INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garou Sliding Simulator', 'Garou Sliding Simulator is a fan-made, informal game inspired by the humorously animated scene of Garou sliding in the One-Punch Man anime. Players control Garou as he slides across the terrain, aiming to travel as far as possible while avoiding various obstacles. The game is simple, comedic, and focused entirely on the sliding mechanic that became a meme among fans.' FROM games WHERE igdb_id = 377715 ON CONFLICT (game_id, language_code) DO NOTHING;
