INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Davy Fresh', 'Super Davy Fresh is a multimedia project by artist Davy Fresh, blending a retro-style, 2D platformer video game with a double hip-hop album, both released in late 2025, offering an immersive cultural experience where music, gameplay, and storytelling merge to empower players and listeners. The game features gameplay like punching executives and tossing vinyls, while the album (two discs, two eras) drops alongside it, creating a unified project for fans.' FROM games WHERE igdb_id = 380954 ON CONFLICT (game_id, language_code) DO NOTHING;
