INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motamo', 'Motamo is a word puzzle game where players must guess a hidden target french word using color-coded hints. Each attempt reveals how close the letters are to the correct solution, creating a logical and linguistic challenge. The game features multiple levels, dictionary definitions, score multipliers, and special tiles that alter the difficulty. Designed to be both fun and educational, Motamo offers a unique mix of wordplay and puzzle mechanics accessible to all players.' FROM games WHERE igdb_id = 361768 ON CONFLICT (game_id, language_code) DO NOTHING;
