INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Backrooms: Mass Extinction', 'If you noclip out of reality in the wrong areas, you''ll end up in the Backrooms. The old moist carpet, the mono-yellow rooms and the hum-buzz of the fluorescent lights will be your only comfort in the endless purgatory you have found yourself in. Don''t bother crying out for help. Nobody is left.' FROM games WHERE igdb_id = 203558 ON CONFLICT (game_id, language_code) DO NOTHING;
