INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IcoNick Duster: Planets Defender', 'Nick Duster, better known as "IcoNick", a war veteran of the intergalactic congregation, who has been brought back to defend the planets from hostile alliances. Control your turret, with high firepower. 3 game modes: Contracts, Asteroids and Invasion. Full of action. Hundreds of galaxies awaits. Go!' FROM games WHERE igdb_id = 371944 ON CONFLICT (game_id, language_code) DO NOTHING;
