INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Momotaro Dentetsu 2: Anata no Machi mo Kitto aru', 'The latest entry in the Momotaro Dentetesu series, Momotaro Dentetsu 2: Anata no Machi mo Kittoaru promises the largest volume of content to date, with approximately 1,000 stations—nearly three times the amount featured in Momotaro Dentetsu: Showa, Heisei, Reiwa mo Teiban!—and over 6,000 properties. The game uses two maps, one for western Japan and one for eastern Japan. The Nintendo Switch 2 Edition features a larger map display, as well as support for camera play.' FROM games WHERE igdb_id = 358542 ON CONFLICT (game_id, language_code) DO NOTHING;
