INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Proxy Project Ouroboros', 'A 3D local splitscreen reimagining of the snake game (can be played single player too), as an infinite wave based score attack where you have to eat different rogue critters who''s AI changes depending on the current level event in the chosen map, with deep customization in both looks and gameplay.' FROM games WHERE igdb_id = 366076 ON CONFLICT (game_id, language_code) DO NOTHING;
