INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Flying Car', 'The Flying Car is an exhilarating endless runner game set in tunnels where players must navigate obstacles, collect points, and seize special items that grant temporary invincibility, double scores, or time slowdowns. As player accumulate points, the pace quickens, intensifying the challenge. Dodge obstacles, gather points, and push your reflexes to the limit in this adrenaline-fueled adventure!' FROM games WHERE igdb_id = 340863 ON CONFLICT (game_id, language_code) DO NOTHING;
