INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wait, Is That Me?', 'Fight hordes of enemies, upgrade your character and conquer bosses. Be wary of your actions, as each one is recorded and will be played back by an exact replica of you in future loops. Your clones can become either allies by fighting alongside you or they can become enemies by damaging you instead.' FROM games WHERE igdb_id = 364653 ON CONFLICT (game_id, language_code) DO NOTHING;
