INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sips and Sonnets', 'Run a tea shop in the British countryside and enkindle your love for poetry in this heartfelt visual novel. Play as Ms Meadows, retired journalist and tea enthusiast, as she prepares for her best friend’s long-awaited visit. Listen to customers’ stories, brew tea, and craft wholehearted poems.' FROM games WHERE igdb_id = 346739 ON CONFLICT (game_id, language_code) DO NOTHING;
