INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrouded Depths', 'Stranded in the fog of the murky waters on an isolated ferry with nothing but your harpoon gun, you feel the overwhelming presence of something within the misty mangrove. Your vessel is stopped dead and it is up to you with the assistance of the Captain to get the boat back up and running again.' FROM games WHERE igdb_id = 375467 ON CONFLICT (game_id, language_code) DO NOTHING;
