INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tusmox', 'Tusmox is a word-game based on the rules of the French TV show Motus, similar to Wordle. It can be played either with friends or alone, and was developed following the discontinuation of the "Tusmo" game.' FROM games WHERE igdb_id = 381412 ON CONFLICT (game_id, language_code) DO NOTHING;
