INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Seed', 'Lost Seed is a single-player visual novel combining RPG and dating sim elements. Featuring over 300,000 words of text and more than 30 beautifully illustrated CGs, the game immerses players in a rich narrative full of fantasy, magic, romance, and mystery. Your decisions shape Mia’s journey and the fate of her companions in a captivating story on the continent of Eden.' FROM games WHERE igdb_id = 361637 ON CONFLICT (game_id, language_code) DO NOTHING;
