INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crystal-veins', 379149, '2025-09-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobejm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc11kfy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Veins', 'Crystal Veins is a charming 2D platformer adventure that blends lighthearted cartoon visuals with intense subterranean challenge. Players take control of Toby, a rookie miner who wakes up trapped deep underground after a mysterious cave-in. With only his pickaxe, helmet, and a flickering lantern, he must dig, dodge, and dash his way through a forgotten mine full of secrets and dangers. Each ancient gate blocking Toby’s path requires a precise number of rare crystals to open. To survive, players must mine the glowing crystal veins hidden throughout the level, evade deadly threats like lava pits, bats, and lurking cave beasts, and race to the exit before the darkness closes in. Packed with satisfying mining mechanics, smooth movement, and puzzle-like level design, Crystal Veins offers a layered, fast-paced experience where every swing and every step matters. Will you dig deep enough to escape... or be lost in the shadows forever?' FROM games WHERE igdb_id = 379149 ON CONFLICT (game_id, language_code) DO NOTHING;
