INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raze Vol. 1', 'Raze Vol. 1 is a satirical punk rock VR puzzle-platformer. Team up with Raze, a punk guitarist zapped into an influencer-run nightmare. Use her power arm, dive into her mind, and spot hidden clues with her damaged eye. Voiced by Lzzy Hale. Story + Arcade modes. Raze is gonna blaze!' FROM games WHERE igdb_id = 364938 ON CONFLICT (game_id, language_code) DO NOTHING;
