INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Near-Death-Expedition', 'After quitting the job, you were casually browsing a video site when you saw a strange video with a blank thumbnail. "Can you hear me? Can you see me...?" The next day, you receive a message requesting you to be the manager of the mysterious VTuber "Owarino Rinne". The endless journey begins.' FROM games WHERE igdb_id = 329233 ON CONFLICT (game_id, language_code) DO NOTHING;
