INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1000 Princes', '1000 Princes is a female-oriented 3D visual novel romance game. A fracture in your timeline has caused all your prince husbands—spanning past, present and future from different settings—to time-travel to your current era. Now1,000 princes coexist on your shared timeline, protecting and adoring you.' FROM games WHERE igdb_id = 323686 ON CONFLICT (game_id, language_code) DO NOTHING;
