INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sleep Awake', 'First-person psychedelic horror set in the far future. In the last known city on Earth, people are disappearing in their sleep. Those who remain exist in a crisis of reckless experiments to keep awake. Katja must navigate depraved death cults, otherworldly forces, and the ever-present horror of The HUSH, to save herself and those who rely upon her.' FROM games WHERE igdb_id = 305012 ON CONFLICT (game_id, language_code) DO NOTHING;
