INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tic Cat Dog', 'A Tic-Tac-Toe game made for friends and family! No more draws—every match has a winner. Easy to learn in minutes, yet hides strategic depth. Perfect for parent-child bonding, couples’ playful duels, or fun with friends. Enjoy a fast, no-draw Tic-Tac-Toe match anytime, anywhere!' FROM games WHERE igdb_id = 366294 ON CONFLICT (game_id, language_code) DO NOTHING;
