INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konkonkon', 'Out of curiosity, I’m walking toward the "town where all the residents disappeared." Suddenly, I hear a noise and turn in that direction, just in time to see a small animal scurrying away. That was... a fox! Come to think of it, what sound do foxes make again? "KONKONKON" is an adventure game.' FROM games WHERE igdb_id = 337741 ON CONFLICT (game_id, language_code) DO NOTHING;
