INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Firefighting Heroes: Truck 911 Simulator', 'Gear up and answer the call with "Firefighting Heroes: Truck 911 Simulator." Step into the role of a dedicated firefighter in this thrilling simulation, where you''ll tackle fires across over 30 diverse areas inspired by real American locations. Experience the urgency of emergency response as you drive fire trucks, wield authentic firefighting tools, and save lives in a variety of challenging scenarios.' FROM games WHERE igdb_id = 336220 ON CONFLICT (game_id, language_code) DO NOTHING;
