INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stahldrache', 'Stahldrache is a top-down shooter set in the skies of far-flung planets. The automated terraforming system has gone rogue, and must be stopped. Fight against time and waves of drones to make the planet safe! Bomb the control nodes and neutralize the AI before the defenseless colony ships arrive!' FROM games WHERE igdb_id = 364952 ON CONFLICT (game_id, language_code) DO NOTHING;
